//! Container profiles are generated by CLI flags, independently of framework templates.
//! Profile container do CLI flag sinh riêng, không nằm trong framework template.

use anyhow::{Context, Result};
use std::path::Path;

use crate::scaffold::processor::{Scaffolder, slugify};
use crate::wizard::engine::ScaffoldConfig;

const KUBERNETES_DNS_LABEL_MAX_BYTES: usize = 63;
const KUBERNETES_RESOURCE_HASH_HEX_LENGTH: usize = 16;
const DEFAULT_WEB_CONTAINER_PORT: u16 = 4315;
const WEB_CONTAINER_UID: u32 = 65532;
const WEB_CONTAINER_GID: u32 = 65532;
const DEFAULT_CONTAINER_PROJECT_DIR: &str = "/app";
const DEFAULT_CONTAINER_DATA_DIR: &str = "/mgc-data";
const DEFAULT_CONTAINER_HOME_DIR: &str = "/tmp";
const DEFAULT_CONTAINER_DATA_VOLUME: &str = "magicore-system-data";
const DEFAULT_CONTAINER_ENTRYPOINT_FILE: &str = "mgc-container-entrypoint";
const DEFAULT_CONTAINER_ENTRYPOINT_PATH: &str = "/usr/local/bin/mgc-container-entrypoint";
const DEFAULT_MGC_IMAGE: &str = concat!("ghcr.io/mingd-153/magicore:", env!("CARGO_PKG_VERSION"));
const DEFAULT_NODE_RUNTIME_IMAGE: &str = "node:26.12.0-trixie-slim";
const DEFAULT_PYTHON_RUNTIME_IMAGE: &str = "python:3.15.0-slim-trixie";
const DEFAULT_RUST_RUNTIME_IMAGE: &str = "rust:1.99.0-slim-trixie";
const DEFAULT_GO_RUNTIME_IMAGE: &str = "golang:1.27.2-trixie";
const DEFAULT_FLUTTER_VERSION: &str = "3.47.7";
const DEFAULT_FLUTTER_ARCHIVE_SHA256: &str =
    "af7455f540df951184c7953fbe3cf884766e7541dacf8571f9f582db03dd6230";
const DEFAULT_FLUTTER_RUNTIME_IMAGE: &str = "debian:trixie-slim";
const DEFAULT_FLUTTER_RELEASE_BASE_URL: &str =
    "https://storage.googleapis.com/flutter_infra_release/releases/stable/linux";

pub(super) fn generate_assets(target: &Path, config: &ScaffoldConfig) -> Result<()> {
    let docker_requested = config.features.iter().any(|feature| feature == "docker");
    let k8s_requested = config.features.iter().any(|feature| feature == "k8s");
    if !docker_requested && !k8s_requested {
        return Ok(());
    }
    if k8s_requested && config.core != "web" {
        return Err(crate::error::k8s_profile_unsupported(&config.core));
    }

    match config.core.as_str() {
        "web" => write_web_docker_assets(target, config)?,
        "ai" => write_ai_docker_assets(target, config)?,
        "clo" => write_clo_docker_assets(target, config)?,
        "lib" => write_lib_docker_assets(target, config)?,
        "app" => write_app_docker_assets(target, config)?,
        core => {
            return Err(crate::error::container_profile_unsupported(
                core,
                &Scaffolder::framework(config),
                "no detected native project manifest",
            ));
        }
    }
    if docker_requested {
        append_docker_readme(target)?;
    }
    if k8s_requested {
        write_web_k8s_assets(target, config)?;
    }
    Ok(())
}

fn append_docker_readme(target: &Path) -> Result<()> {
    let path = target.join("README.md");
    let mut readme = match std::fs::read_to_string(&path) {
        Ok(readme) => readme,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => String::from("# Project\n"),
        Err(error) => return Err(error).with_context(|| format!("read {}", path.display())),
    };
    if readme.contains("docker compose up --build") && readme.contains("copies that same lock") {
        return Ok(());
    }
    if !readme.ends_with('\n') {
        readme.push('\n');
    }
    readme.push_str(
        "\n## Docker\n\nRun `mgc install` in this directory to create the project lockfile, then run `docker compose up --build`. The image copies that same lock and uses `mgc install --frozen`; dependency resolution and lifecycle remain identical between the host project and container.\n",
    );
    Scaffolder::write_file(&path, &readme)
}

/// Generate the AI development container from the MGC scaffold itself.
/// Registry templates may add framework files, but a missing optional
/// template layer must never silently turn `--docker` into a no-op.
/// (Sinh container AI từ chính MGC scaffold. Thiếu template registry
/// tùy chọn không được khiến `--docker` âm thầm không làm gì.)
fn write_ai_docker_assets(target: &Path, config: &ScaffoldConfig) -> Result<()> {
    if !target.join("pyproject.toml").is_file() {
        return Err(crate::error::container_manifest_required(
            "ai",
            &Scaffolder::framework(config),
            "pyproject.toml",
        ));
    }

    let mgc_image = DEFAULT_MGC_IMAGE;
    let dockerfile = format!(
        "ARG MGC_IMAGE={mgc_image}\n\
         ARG PYTHON_IMAGE={DEFAULT_PYTHON_RUNTIME_IMAGE}\n\
         FROM ${{MGC_IMAGE}} AS mgc-cli\n\
         FROM ${{PYTHON_IMAGE}}\n\
         WORKDIR {DEFAULT_CONTAINER_PROJECT_DIR}\n\
         COPY --from=mgc-cli /usr/local/bin/mgc /usr/local/bin/mgc\n\
         COPY --from=mgc-cli /usr/lib/libz.so.1 /usr/lib/libz.so.1\n\
         COPY --from=mgc-cli /etc/ssl/certs/ca-certificates.crt /etc/ssl/certs/ca-certificates.crt\n\
         COPY --from=mgc-cli --chown={WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} {DEFAULT_CONTAINER_DATA_DIR} {DEFAULT_CONTAINER_DATA_DIR}\n\
         COPY {DEFAULT_CONTAINER_ENTRYPOINT_FILE} {DEFAULT_CONTAINER_ENTRYPOINT_PATH}\n\
         RUN chmod 0555 {DEFAULT_CONTAINER_ENTRYPOINT_PATH}\n\
         COPY --chown={WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} . .\n\
         ENV MGC_DATA_DIR={DEFAULT_CONTAINER_DATA_DIR} HOME={DEFAULT_CONTAINER_HOME_DIR} SSL_CERT_FILE=/etc/ssl/certs/ca-certificates.crt PYTHONDONTWRITEBYTECODE=1\n\
         RUN chown {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} {DEFAULT_CONTAINER_PROJECT_DIR} {DEFAULT_CONTAINER_DATA_DIR}\n\
         USER {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID}\n\
         RUN mgc install --frozen\n\
         RUN mgc test\n\
         RUN mgc build\n\
         ENTRYPOINT [\"{DEFAULT_CONTAINER_ENTRYPOINT_PATH}\"]\n\
         CMD [\"dev\"]\n"
    );
    let image_name = container_resource_name("ai", config);
    let compose = container_compose(&image_name, mgc_image, "dev");
    Scaffolder::write_file(&target.join("Dockerfile"), &dockerfile)?;
    Scaffolder::write_file(&target.join(".dockerignore"), container_dockerignore())?;
    write_container_entrypoint(target, "mgc install")?;
    Scaffolder::write_file(&target.join("docker-compose.yml"), &compose)?;
    Ok(())
}

/// Generate a CDK validation image whose dependencies and synth lifecycle
/// remain owned by MagiCore; it does not deploy to a cloud account.
/// (Sinh image kiểm thử CDK; dependency/build qua MGC và không deploy lên cloud.)
fn write_clo_docker_assets(target: &Path, config: &ScaffoldConfig) -> Result<()> {
    let framework = Scaffolder::framework(config);
    if !matches!(framework.as_str(), "cdk" | "cdk-typescript")
        || !target.join("package.json").is_file()
        || !target.join("cdk.json").is_file()
    {
        return Err(crate::error::container_profile_unsupported(
            "clo",
            &framework,
            "verified CDK TypeScript manifests (package.json and cdk.json)",
        ));
    }

    let mgc_image = DEFAULT_MGC_IMAGE;
    let dockerfile = format!(
        "ARG MGC_IMAGE={mgc_image}\n\
         ARG NODE_IMAGE={DEFAULT_NODE_RUNTIME_IMAGE}\n\
         FROM ${{MGC_IMAGE}} AS mgc-cli\n\
         FROM ${{NODE_IMAGE}}\n\
         WORKDIR {DEFAULT_CONTAINER_PROJECT_DIR}\n\
         COPY --from=mgc-cli /usr/local/bin/mgc /usr/local/bin/mgc\n\
         COPY --from=mgc-cli /usr/lib/libz.so.1 /usr/lib/libz.so.1\n\
         COPY --from=mgc-cli /etc/ssl/certs/ca-certificates.crt /etc/ssl/certs/ca-certificates.crt\n\
         COPY --from=mgc-cli --chown={WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} {DEFAULT_CONTAINER_DATA_DIR} {DEFAULT_CONTAINER_DATA_DIR}\n\
         COPY {DEFAULT_CONTAINER_ENTRYPOINT_FILE} {DEFAULT_CONTAINER_ENTRYPOINT_PATH}\n\
         RUN chmod 0555 {DEFAULT_CONTAINER_ENTRYPOINT_PATH}\n\
         COPY --chown={WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} . .\n\
         ENV MGC_DATA_DIR={DEFAULT_CONTAINER_DATA_DIR} HOME={DEFAULT_CONTAINER_HOME_DIR} SSL_CERT_FILE=/etc/ssl/certs/ca-certificates.crt\n\
         RUN chown {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} {DEFAULT_CONTAINER_PROJECT_DIR} {DEFAULT_CONTAINER_DATA_DIR}\n\
         USER {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID}\n\
         RUN mgc install --frozen\n\
         RUN mgc test\n\
         RUN mgc build\n\
         ENTRYPOINT [\"{DEFAULT_CONTAINER_ENTRYPOINT_PATH}\"]\n\
         CMD [\"build\"]\n"
    );
    let image_name = container_resource_name("clo", config);
    let compose = container_compose(&image_name, mgc_image, "build");
    Scaffolder::write_file(&target.join("Dockerfile"), &dockerfile)?;
    Scaffolder::write_file(&target.join(".dockerignore"), container_dockerignore())?;
    write_container_entrypoint(target, "mgc install")?;
    Scaffolder::write_file(&target.join("docker-compose.yml"), &compose)?;
    Ok(())
}

/// Generate a Rust library build/test image whose dependency lifecycle is
/// owned by MGC and whose compiler runs offline after `mgc install`.
/// (Sinh image test/build thư viện; MGC sở hữu dependency, toolchain chạy theo lock.)
fn write_lib_docker_assets(target: &Path, config: &ScaffoldConfig) -> Result<()> {
    let runtime_image = if target.join("Cargo.toml").is_file() {
        DEFAULT_RUST_RUNTIME_IMAGE
    } else if target.join("go.mod").is_file() {
        DEFAULT_GO_RUNTIME_IMAGE
    } else if target.join("pyproject.toml").is_file() {
        DEFAULT_PYTHON_RUNTIME_IMAGE
    } else if target.join("package.json").is_file() {
        DEFAULT_NODE_RUNTIME_IMAGE
    } else {
        return Err(crate::error::container_profile_unsupported(
            "lib",
            &Scaffolder::framework(config),
            "no detected Rust, Go, Python, or Node manifest",
        ));
    };

    let mgc_image = DEFAULT_MGC_IMAGE;
    let dockerfile = format!(
        "ARG MGC_IMAGE={mgc_image}\n\
         ARG TOOLCHAIN_IMAGE={runtime_image}\n\
         FROM ${{MGC_IMAGE}} AS mgc-cli\n\
         FROM ${{TOOLCHAIN_IMAGE}}\n\
         WORKDIR {DEFAULT_CONTAINER_PROJECT_DIR}\n\
         COPY --from=mgc-cli /usr/local/bin/mgc /usr/local/bin/mgc\n\
         COPY --from=mgc-cli /usr/lib/libz.so.1 /usr/lib/libz.so.1\n\
         COPY --from=mgc-cli /etc/ssl/certs/ca-certificates.crt /etc/ssl/certs/ca-certificates.crt\n\
         COPY --from=mgc-cli --chown={WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} {DEFAULT_CONTAINER_DATA_DIR} {DEFAULT_CONTAINER_DATA_DIR}\n\
         COPY {DEFAULT_CONTAINER_ENTRYPOINT_FILE} {DEFAULT_CONTAINER_ENTRYPOINT_PATH}\n\
         RUN chmod 0555 {DEFAULT_CONTAINER_ENTRYPOINT_PATH}\n\
         COPY --chown={WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} . .\n\
         ENV MGC_DATA_DIR={DEFAULT_CONTAINER_DATA_DIR} HOME={DEFAULT_CONTAINER_HOME_DIR} SSL_CERT_FILE=/etc/ssl/certs/ca-certificates.crt\n\
         RUN chown {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} {DEFAULT_CONTAINER_PROJECT_DIR} {DEFAULT_CONTAINER_DATA_DIR}\n\
         USER {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID}\n\
         RUN mgc install --frozen\n\
         RUN mgc test\n\
         RUN mgc build\n\
         ENTRYPOINT [\"{DEFAULT_CONTAINER_ENTRYPOINT_PATH}\"]\n\
         CMD [\"test\"]\n"
    );
    let image_name = container_resource_name("lib", config);
    let compose = container_compose(&image_name, mgc_image, "test");
    Scaffolder::write_file(&target.join("Dockerfile"), &dockerfile)?;
    Scaffolder::write_file(&target.join(".dockerignore"), container_dockerignore())?;
    write_container_entrypoint(target, "mgc install")?;
    Scaffolder::write_file(&target.join("docker-compose.yml"), &compose)?;
    Ok(())
}

fn container_resource_name(core: &str, config: &ScaffoldConfig) -> String {
    format!(
        "magicore-{core}-{}:local",
        slugify(&Scaffolder::config_display_name(config))
    )
}

fn container_compose(image: &str, mgc_image: &str, command: &str) -> String {
    format!(
        "services:\n\
         \x20\x20app:\n\
         \x20\x20\x20\x20build:\n\
         \x20\x20\x20\x20\x20\x20context: .\n\
         \x20\x20\x20\x20\x20\x20args:\n\
         \x20\x20\x20\x20\x20\x20\x20\x20MGC_IMAGE: ${{MGC_IMAGE:-{mgc_image}}}\n\
         \x20\x20\x20\x20image: ${{MGC_IMAGE_NAME:-{image}}}\n\
         \x20\x20\x20\x20init: true\n\
         \x20\x20\x20\x20command: [\"{command}\"]\n\
         \x20\x20\x20\x20volumes:\n\
         \x20\x20\x20\x20\x20\x20- mgc-data:{DEFAULT_CONTAINER_DATA_DIR}\n\
         volumes:\n\
         \x20\x20mgc-data:\n\
         \x20\x20\x20\x20name: ${{MGC_DATA_VOLUME:-{DEFAULT_CONTAINER_DATA_VOLUME}}}\n"
    )
}

/// Replay the project lock into the shared MGC store before dispatching
/// the requested command, so a reused volume has the locked artifacts.
/// (Cài lại theo lock project vào store MGC dùng chung trước command,
/// để volume dùng lại có đúng artifact đã ghim.)
fn write_container_entrypoint(target: &Path, install_command: &str) -> Result<()> {
    let script = format!(
        "#!/bin/sh\n\
         # Replay the project lock into the shared MGC store.\n\
         # Cài theo lock project vào store MGC dùng chung.\n\
         set -eu\n\
         {install_command} --frozen\n\
         exec mgc \"$@\"\n"
    );
    Scaffolder::write_file(&target.join(DEFAULT_CONTAINER_ENTRYPOINT_FILE), &script)
}

fn container_dockerignore() -> &'static str {
    ".git\n.env\n.env.*\n.magicore/cache\n.magicore/store\n.magicore/exec.log\nnode_modules\n.dart_tool\n.flutter-plugins\n.flutter-plugins-dependencies\n.gradle\nPods\ntarget\nbuild\ndist\n"
}

/// Generate the verified Flutter web-test container with MGC owning Pub dependencies.
/// Sinh container Flutter web-test đã xác minh; MGC sở hữu dependency Pub.
fn write_app_docker_assets(target: &Path, config: &ScaffoldConfig) -> Result<()> {
    let framework = Scaffolder::framework(config);
    if framework != "flutter" || !target.join("pubspec.yaml").is_file() {
        return Err(crate::error::container_manifest_required(
            "app",
            &framework,
            "pubspec.yaml (Flutter profile)",
        ));
    }

    let mgc_image = DEFAULT_MGC_IMAGE;
    let dockerfile = format!(
        "ARG MGC_IMAGE={mgc_image}\n\
         ARG FLUTTER_IMAGE={DEFAULT_FLUTTER_RUNTIME_IMAGE}\n\
         ARG FLUTTER_VERSION={DEFAULT_FLUTTER_VERSION}\n\
         ARG FLUTTER_ARCHIVE_SHA256={DEFAULT_FLUTTER_ARCHIVE_SHA256}\n\
         ARG FLUTTER_RELEASE_BASE_URL={DEFAULT_FLUTTER_RELEASE_BASE_URL}\n\
         FROM ${{MGC_IMAGE}} AS mgc-cli\n\
         FROM ${{FLUTTER_IMAGE}}\n\
         ARG FLUTTER_VERSION\n\
         ARG FLUTTER_ARCHIVE_SHA256\n\
         ARG FLUTTER_RELEASE_BASE_URL\n\
         RUN apt-get update && apt-get install -y --no-install-recommends ca-certificates curl git unzip xz-utils zip libglu1-mesa && rm -rf /var/lib/apt/lists/*\n\
         RUN curl --fail --location --silent --show-error \"${{FLUTTER_RELEASE_BASE_URL}}/flutter_linux_${{FLUTTER_VERSION}}-stable.tar.xz\" --output /tmp/flutter.tar.xz && echo \"${{FLUTTER_ARCHIVE_SHA256}}  /tmp/flutter.tar.xz\" | sha256sum --check --strict - && tar -xJf /tmp/flutter.tar.xz -C /opt && rm /tmp/flutter.tar.xz\n\
         RUN chown -R {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} /opt/flutter\n\
         ENV PATH=/opt/flutter/bin:$PATH HOME={DEFAULT_CONTAINER_HOME_DIR}\n\
         USER {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID}\n\
         RUN /opt/flutter/bin/flutter config --no-analytics && /opt/flutter/bin/flutter precache --web\n\
         USER 0:0\n\
         WORKDIR {DEFAULT_CONTAINER_PROJECT_DIR}\n\
         COPY --from=mgc-cli /usr/local/bin/mgc /usr/local/bin/mgc\n\
         COPY --from=mgc-cli /usr/lib/libz.so.1 /usr/lib/libz.so.1\n\
         COPY --from=mgc-cli /etc/ssl/certs/ca-certificates.crt /etc/ssl/certs/ca-certificates.crt\n\
         COPY --from=mgc-cli --chown={WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} {DEFAULT_CONTAINER_DATA_DIR} {DEFAULT_CONTAINER_DATA_DIR}\n\
         COPY {DEFAULT_CONTAINER_ENTRYPOINT_FILE} {DEFAULT_CONTAINER_ENTRYPOINT_PATH}\n\
         COPY --chown={WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} . .\n\
         ENV PATH=/opt/flutter/bin:$PATH MGC_DATA_DIR={DEFAULT_CONTAINER_DATA_DIR} HOME={DEFAULT_CONTAINER_HOME_DIR} SSL_CERT_FILE=/etc/ssl/certs/ca-certificates.crt\n\
         RUN chmod 0555 {DEFAULT_CONTAINER_ENTRYPOINT_PATH}\n\
         RUN chown {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} {DEFAULT_CONTAINER_PROJECT_DIR} {DEFAULT_CONTAINER_DATA_DIR}\n\
         USER {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID}\n\
         RUN mgc install --frozen && mgc test && mgc build\n\
         ENTRYPOINT [\"{DEFAULT_CONTAINER_ENTRYPOINT_PATH}\"]\n\
         CMD [\"test\"]\n"
    );
    let image_name = container_resource_name("app", config);
    let compose = container_compose(&image_name, mgc_image, "test");
    Scaffolder::write_file(&target.join("Dockerfile"), &dockerfile)?;
    Scaffolder::write_file(&target.join(".dockerignore"), container_dockerignore())?;
    write_container_entrypoint(target, "mgc install")?;
    Scaffolder::write_file(&target.join("docker-compose.yml"), &compose)?;
    Ok(())
}

fn write_web_docker_assets(target: &Path, config: &ScaffoldConfig) -> Result<()> {
    if matches!(config.sub_type.as_str(), "fullstack" | "monorepo") {
        return Err(crate::error::web_container_runtime_split_unsupported());
    }
    let (runtime_image, runtime_env, is_node) = if target.join("package.json").is_file() {
        (DEFAULT_NODE_RUNTIME_IMAGE, "", true)
    } else if target.join("go.mod").is_file() {
        (
            DEFAULT_GO_RUNTIME_IMAGE,
            "ENV GOPROXY=off GOSUMDB=off GOTOOLCHAIN=local\n",
            false,
        )
    } else if target.join("Cargo.toml").is_file() {
        (
            DEFAULT_RUST_RUNTIME_IMAGE,
            "ENV CARGO_NET_OFFLINE=true\n",
            false,
        )
    } else if target.join("pyproject.toml").is_file() {
        (
            DEFAULT_PYTHON_RUNTIME_IMAGE,
            "ENV PYTHONDONTWRITEBYTECODE=1 PYTHONUNBUFFERED=1\n",
            false,
        )
    } else {
        return Err(crate::error::container_profile_unsupported(
            "web",
            &Scaffolder::framework(config),
            "a native Node, Go, Rust, or PEP 621 Python dependency manifest",
        ));
    };
    let mgc_image = DEFAULT_MGC_IMAGE;
    let dockerfile = format!(
        "ARG MGC_IMAGE={mgc_image}\n\
         ARG TOOLCHAIN_IMAGE={runtime_image}\n\
         FROM ${{MGC_IMAGE}} AS mgc-cli\n\
         FROM ${{TOOLCHAIN_IMAGE}}\n\
         WORKDIR {DEFAULT_CONTAINER_PROJECT_DIR}\n\
         COPY --from=mgc-cli /usr/local/bin/mgc /usr/local/bin/mgc\n\
         COPY --from=mgc-cli /usr/lib/libz.so.1 /usr/lib/libz.so.1\n\
         COPY --from=mgc-cli /etc/ssl/certs/ca-certificates.crt /etc/ssl/certs/ca-certificates.crt\n\
         COPY --from=mgc-cli --chown={WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} {DEFAULT_CONTAINER_DATA_DIR} {DEFAULT_CONTAINER_DATA_DIR}\n\
         COPY {DEFAULT_CONTAINER_ENTRYPOINT_FILE} {DEFAULT_CONTAINER_ENTRYPOINT_PATH}\n\
         ENV MGC_DATA_DIR={DEFAULT_CONTAINER_DATA_DIR} HOME={DEFAULT_CONTAINER_HOME_DIR} SSL_CERT_FILE=/etc/ssl/certs/ca-certificates.crt\n\
         {runtime_env}\
         COPY --chown={WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} . .\n\
         RUN chmod 0555 {DEFAULT_CONTAINER_ENTRYPOINT_PATH}\n\
         RUN chown {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID} {DEFAULT_CONTAINER_PROJECT_DIR} {DEFAULT_CONTAINER_DATA_DIR}\n\
         USER {WEB_CONTAINER_UID}:{WEB_CONTAINER_GID}\n\
         RUN mgc install-web --frozen\n\
         {node_test_step}\
         EXPOSE {DEFAULT_WEB_CONTAINER_PORT}\n\
         ENTRYPOINT [\"{DEFAULT_CONTAINER_ENTRYPOINT_PATH}\"]\n\
         CMD [\"dev\", \"--host\", \"0.0.0.0\", \"--port\", \"{DEFAULT_WEB_CONTAINER_PORT}\"]\n",
        node_test_step = if is_node { "RUN mgc test\n" } else { "" },
    );
    let image_name = format!("{}:local", web_container_resource_name(config));
    let compose = format!(
        "services:\n\
         \x20 app:\n\
         \x20\x20 build:\n\
         \x20\x20\x20 context: .\n\
         \x20\x20\x20 args:\n\
         \x20\x20\x20\x20 MGC_IMAGE: ${{MGC_IMAGE:-{mgc_image}}}\n\
         \x20\x20 image: ${{MGC_IMAGE_NAME:-{image_name}}}\n\
         \x20\x20 init: true\n\
         \x20\x20 ports:\n\
         \x20\x20\x20 - \"{DEFAULT_WEB_CONTAINER_PORT}:{DEFAULT_WEB_CONTAINER_PORT}\"\n\
         \x20\x20 volumes:\n\
         \x20\x20\x20 - mgc-data:{DEFAULT_CONTAINER_DATA_DIR}\n\
         \x20\x20 restart: unless-stopped\n\
         \n\
         volumes:\n\
         \x20 mgc-data:\n\
         \x20\x20 name: ${{MGC_DATA_VOLUME:-{DEFAULT_CONTAINER_DATA_VOLUME}}}\n"
    );
    let dockerignore = ".git\n.env\n.env.*\n.magicore/cache\n.magicore/store\n.magicore/exec.log\nnode_modules\ntarget\ndist\n";

    Scaffolder::write_file(&target.join("Dockerfile"), &dockerfile)?;
    Scaffolder::write_file(&target.join(".dockerignore"), dockerignore)?;
    write_container_entrypoint(target, "mgc install-web")?;
    Scaffolder::write_file(&target.join("docker-compose.yml"), &compose)?;
    Ok(())
}

/// Emit a local-kind development Deployment using the image built by the
/// generated Dockerfile. This is explicitly a `mgc dev` lane, not a
/// production release manifest.
/// (Sinh Deployment cho local kind, chạy `mgc dev`; không gắn nhãn production.)
fn write_web_k8s_assets(target: &Path, config: &ScaffoldConfig) -> Result<()> {
    let name = web_container_resource_name(config);
    let image = format!("{name}:local");
    let probe_path = if target.join("package.json").is_file() {
        "/"
    } else {
        "/api/health"
    };
    let manifest = format!(
        "apiVersion: apps/v1\n\
         kind: Deployment\n\
         metadata:\n\
         \x20 name: {name}\n\
         \x20 labels:\n\
         \x20\x20 app.kubernetes.io/name: {name}\n\
         spec:\n\
         \x20 replicas: 1\n\
         \x20 selector:\n\
         \x20\x20 matchLabels:\n\
         \x20\x20\x20 app.kubernetes.io/name: {name}\n\
         \x20 template:\n\
         \x20\x20 metadata:\n\
         \x20\x20\x20 labels:\n\
         \x20\x20\x20\x20 app.kubernetes.io/name: {name}\n\
         \x20\x20 spec:\n\
         \x20\x20\x20 automountServiceAccountToken: false\n\
         \x20\x20\x20 securityContext:\n\
         \x20\x20\x20\x20 runAsNonRoot: true\n\
         \x20\x20\x20\x20 runAsUser: {WEB_CONTAINER_UID}\n\
         \x20\x20\x20\x20 runAsGroup: {WEB_CONTAINER_GID}\n\
         \x20\x20\x20\x20 fsGroup: {WEB_CONTAINER_GID}\n\
         \x20\x20\x20\x20 seccompProfile:\n\
         \x20\x20\x20\x20\x20 type: RuntimeDefault\n\
         \x20\x20\x20 containers:\n\
         \x20\x20\x20 - name: web\n\
         \x20\x20\x20\x20 image: {image}\n\
         \x20\x20\x20\x20 imagePullPolicy: IfNotPresent\n\
         \x20\x20\x20\x20 ports:\n\
         \x20\x20\x20\x20 - name: http\n\
         \x20\x20\x20\x20\x20 containerPort: {DEFAULT_WEB_CONTAINER_PORT}\n\
         \x20\x20\x20\x20 env:\n\
         \x20\x20\x20\x20 - name: MGC_DATA_DIR\n\
         \x20\x20\x20\x20\x20 value: {DEFAULT_CONTAINER_DATA_DIR}\n\
         \x20\x20\x20\x20 startupProbe:\n\
         \x20\x20\x20\x20\x20 httpGet:\n\
         \x20\x20\x20\x20\x20\x20 path: {probe_path}\n\
         \x20\x20\x20\x20\x20\x20 port: http\n\
         \x20\x20\x20\x20\x20 periodSeconds: 5\n\
         \x20\x20\x20\x20\x20 failureThreshold: 36\n\
         \x20\x20\x20\x20 readinessProbe:\n\
         \x20\x20\x20\x20\x20 httpGet:\n\
         \x20\x20\x20\x20\x20\x20 path: {probe_path}\n\
         \x20\x20\x20\x20\x20\x20 port: http\n\
         \x20\x20\x20\x20 livenessProbe:\n\
         \x20\x20\x20\x20\x20 httpGet:\n\
         \x20\x20\x20\x20\x20\x20 path: {probe_path}\n\
         \x20\x20\x20\x20\x20\x20 port: http\n\
         \x20\x20\x20\x20 securityContext:\n\
         \x20\x20\x20\x20\x20 allowPrivilegeEscalation: false\n\
         \x20\x20\x20\x20\x20 capabilities:\n\
         \x20\x20\x20\x20\x20\x20 drop: [ALL]\n\
         ---\n\
         apiVersion: v1\n\
         kind: Service\n\
         metadata:\n\
         \x20 name: {name}\n\
         spec:\n\
         \x20 selector:\n\
         \x20\x20 app.kubernetes.io/name: {name}\n\
         \x20 ports:\n\
         \x20 - name: http\n\
         \x20\x20 protocol: TCP\n\
         \x20\x20 port: {DEFAULT_WEB_CONTAINER_PORT}\n\
         \x20\x20 targetPort: http\n\
         \x20 type: ClusterIP\n"
    );
    let readme = format!(
        "# Kubernetes development lane\n\nThis manifest runs `mgc dev` in a local cluster for development and E2E validation. It is not a production deployment profile.\n\nRun `mgc install` in the project first to create the lockfile consumed by the image. Build and load the image into kind, then apply the manifest:\n\n```sh\ndocker build -t {image} .\nkind load docker-image {image}\nkubectl apply -f k8s/deployment.yaml\n```\n\nThe generated image copies the project lock and runs `mgc install-web --frozen` before `mgc dev`. The pod runs as UID/GID 65532 with dropped Linux capabilities. Runtime MGC writes live in the pod's writable layer and are discarded when the pod is replaced.\n"
    );
    Scaffolder::write_file(&target.join("k8s").join("deployment.yaml"), &manifest)?;
    Scaffolder::write_file(&target.join("k8s").join("README.md"), &readme)?;
    Ok(())
}

/// Produce a stable image/resource name that fits Kubernetes DNS label limits.
/// Sinh tên image/resource ổn định và không vượt giới hạn DNS label của Kubernetes.
fn web_container_resource_name(config: &ScaffoldConfig) -> String {
    const PREFIX: &str = "magicore-";
    let display_name = Scaffolder::config_display_name(config);
    let slug = slugify(&display_name);
    if PREFIX.len() + slug.len() <= KUBERNETES_DNS_LABEL_MAX_BYTES {
        return format!("{PREFIX}{slug}");
    }

    let hash = blake3::hash(display_name.as_bytes()).to_hex().to_string();
    let readable_length =
        KUBERNETES_DNS_LABEL_MAX_BYTES - PREFIX.len() - 1 - KUBERNETES_RESOURCE_HASH_HEX_LENGTH;
    format!(
        "{PREFIX}{}-{}",
        &slug[..readable_length],
        &hash[..KUBERNETES_RESOURCE_HASH_HEX_LENGTH]
    )
}
